import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 13 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics, passages, and answer keys are
 * distinct from earlier practice tests. Explanations are deliberately fuller:
 * Math items give a full step-by-step solution; R&W items state why the
 * correct choice is right and why each distractor fails.
 */

// ─────────────────────── PRACTICE TEST 13 · R&W M1 (27) ──────────────────────
const T13_RW_M1: SatQuestion[] = [
  { id: "t13rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The lecturer's argument was admirably ______: she stated her thesis once, defended it in three crisp paragraphs, and stopped.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["economical", "rambling", "ornate", "evasive"], correct: 0, explanation: "The answer is (A) \"economical.\" The sentence describes an argument that states its thesis once, defends it in just three crisp paragraphs, and then stops — prose that uses no more words than necessary. \"Economical\" precisely names that sparing, efficient use of language. (B) \"rambling\" means wandering on at length, the direct opposite of stating a point once and stopping. (C) \"ornate\" means elaborately decorated; nothing here is decorative, and the praise is for brevity, not flourish. (D) \"evasive\" means dodging or avoiding the point, but the lecturer plainly states and defends her thesis rather than avoiding it." },
  { id: "t13rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of seven advisers ______ scheduled to meet again next Tuesday.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were being"], correct: 0, explanation: "The answer is (A) \"is.\" This tests subject-verb agreement across an intervening prepositional phrase. The true subject is the singular collective noun \"committee\"; \"of seven advisers\" is a prepositional phrase whose object cannot be the subject. A singular subject takes the singular verb \"is.\" (B) \"are\" and (D) \"were being\" are plural and (C) \"have been\" is plural — all three wrongly agree with the nearby plural \"advisers\" instead of with the head noun \"committee.\" The trap is letting the closest noun, rather than the grammatical subject, drive the verb." },
  { id: "t13rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Coral polyps deposit calcium carbonate to build the reef's skeleton, but they depend on algae living in their tissues to supply most of the energy that powers this construction.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Reef-building corals rely on resident algae for the energy they use to construct their skeletons.", "Coral polyps build reefs entirely without outside help.", "Algae destroy the calcium carbonate skeletons of reefs.", "Reefs are made of algae rather than calcium carbonate."], correct: 0, explanation: "The answer is (A). The passage makes two points: coral polyps deposit calcium carbonate to build the reef's skeleton, AND they depend on resident algae to supply most of the energy that powers that construction. Choice A captures both — corals rely on the algae for the energy used to build their skeletons. (B) contradicts the text, which states polyps \"depend on algae,\" so they do not build \"entirely without outside help.\" (C) reverses the algae's role: the text says algae supply energy for building, not that they destroy the skeleton. (D) misidentifies the skeleton's material — the text says it is calcium carbonate, not algae." },
  { id: "t13rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail had been washed out by spring floods. ______, the rangers closed it until repairs could be made.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Accordingly", "However", "By contrast"], correct: 1, explanation: "The answer is (B) \"Accordingly.\" The first sentence states a cause — the trail was washed out by floods — and the second states the effect: the rangers closed it. \"Accordingly\" means \"as a result,\" which is exactly the cause-and-effect relationship needed. (A) \"Nevertheless,\" (C) \"However,\" and (D) \"By contrast\" all signal opposition or concession, but there is no contrast here; closing the washed-out trail is the natural consequence of the damage, not a reversal of it." },
  { id: "t13rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The kit contained everything a beginner needs ______ brushes, paints, and a small canvas.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["needs, ", "needs: ", "needs; ", "needs "], correct: 1, explanation: "The answer is (B) \"needs: \" (colon). The clause before the blank, \"The kit contained everything a beginner needs,\" is grammatically complete and independent. A colon is the correct mark to introduce the list that then specifies what those things are: brushes, paints, and a canvas. (A) a comma is too weak to introduce an explanatory list after a complete clause. (C) a semicolon must join two independent clauses, but \"brushes, paints, and a small canvas\" is not an independent clause. (D) no punctuation runs the list directly into the clause with no needed signal that an explanation follows." },
  { id: "t13rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the memoir refreshingly ______, since the author admitted to mistakes most writers would have quietly omitted.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["candid", "guarded", "boastful", "fictional"], correct: 0, explanation: "The answer is (A) \"candid.\" The clue is that the author \"admitted to mistakes most writers would have quietly omitted\" — open, honest confession of flaws. \"Candid\" means frank and truthful, which fits exactly. (B) \"guarded\" means cautious and withholding, the opposite of openly admitting mistakes. (C) \"boastful\" means full of self-praise, but confessing errors is the reverse of bragging. (D) \"fictional\" means invented or untrue, which contradicts both the genre (a memoir is nonfiction) and the honesty the sentence praises." },
  { id: "t13rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The scholarship is awarded only to applicants who have completed at least sixty volunteer hours and who maintain a grade average above 3.5.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["An applicant with forty volunteer hours cannot receive the scholarship.", "Any applicant with a high grade average automatically wins.", "Volunteer hours alone guarantee the award.", "The scholarship has no academic requirement."], correct: 0, explanation: "The answer is (A). The scholarship requires BOTH at least sixty volunteer hours AND a grade average above 3.5. Forty volunteer hours falls short of the sixty-hour minimum, so that applicant fails a required condition and cannot receive the award — exactly choice A. (B) ignores the volunteer requirement: a high grade average alone does not satisfy the hours condition, so it cannot \"automatically\" win. (C) ignores the grade requirement in the same way — hours alone do not \"guarantee\" the award. (D) directly contradicts the text, which states a 3.5 academic minimum." },
  { id: "t13rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The new sensor cut the factory's defect rate. ______, it lowered the energy each machine consumed.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Otherwise", "Instead"], correct: 1, explanation: "The answer is (B) \"In addition.\" The first sentence names one benefit of the sensor (it cut the defect rate) and the second names a second benefit (it lowered energy use). Because the sentences pile up two advantages of the same kind, the additive transition \"In addition\" is correct. (A) \"However\" and (D) \"Instead\" signal contrast or replacement, but the two benefits do not oppose each other. (C) \"Otherwise\" introduces an alternative or consequence-of-not-doing-something, which has no place between two stacked positives." },
  { id: "t13rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The novel's plot is so ______ that readers must keep a chart of the characters' shifting alliances to follow it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["intricate", "predictable", "thin", "dull"], correct: 0, explanation: "The answer is (A) \"intricate.\" The sentence says readers must keep a chart of shifting alliances just to follow the plot — a sign of dense, interwoven complexity. \"Intricate\" means elaborately complicated, which fits. (B) \"predictable\" and (C) \"thin\" both describe simple or easily-followed plots, the opposite of one requiring a chart. (D) \"dull\" describes how boring something is, a matter of tone, not the structural complexity the sentence is actually measuring." },
  { id: "t13rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Desert kangaroo rats obtain nearly all the water they need from the seeds they eat, producing such concentrated urine that they almost never drink.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Kangaroo rats meet their water needs through their diet and rarely drink.", "Kangaroo rats drink large amounts of water daily.", "Kangaroo rats eat no seeds.", "Kangaroo rats cannot survive in deserts."], correct: 0, explanation: "The answer is (A). The passage states that kangaroo rats obtain nearly all their water from the seeds they eat and, producing very concentrated urine, almost never drink. Choice A restates exactly this: they meet their water needs through diet and rarely drink. (B) contradicts \"almost never drink.\" (C) contradicts the text, which says they get water from \"the seeds they eat.\" (D) is refuted by the opening reference to \"Desert kangaroo rats,\" which shows they survive in deserts precisely because of this adaptation." },
  { id: "t13rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the manager nor the cashiers ______ aware that the register had been miscounted.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "is", "were", "has been"], correct: 2, explanation: "The answer is (C) \"were.\" This tests the proximity rule for \"neither…nor\" subjects: the verb agrees with whichever subject is nearer to it. The nearer subject is the plural \"cashiers,\" so the plural verb \"were\" is required. (A) \"was,\" (B) \"is,\" and (D) \"has been\" are all singular; they would be correct only if the closer noun were singular (for example, \"Neither the cashiers nor the manager was…\"). The trap is matching the verb to the first, singular noun \"manager\" instead of the nearer plural." },
  { id: "t13rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The drought devastated the region's wheat harvest. ______, farmers who had switched to drought-tolerant millet reported near-normal yields.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "By contrast", "Likewise", "In short"], correct: 1, explanation: "The answer is (B) \"By contrast.\" The first sentence describes a devastated wheat harvest; the second describes farmers who grew millet instead and got near-normal yields. These two outcomes are opposites, so the contrasting transition \"By contrast\" fits. (A) \"Therefore\" signals a consequence, but near-normal millet yields are not a result of the wheat failure. (C) \"Likewise\" signals similarity, yet the outcomes differ sharply. (D) \"In short\" introduces a summary, but the second sentence adds a new, opposing case rather than summarizing the first." },
  { id: "t13rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study reported attendance at 41% for the 7 a.m. class, 68% for the noon class, and 73% for the 5 p.m. class.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Attendance was lowest for the earliest class.", "Attendance was highest for the earliest class.", "The noon class had higher attendance than the evening class.", "All three classes had equal attendance."], correct: 0, explanation: "The answer is (A). Compare the three figures: 7 a.m. = 41%, noon = 68%, 5 p.m. = 73%. The smallest is 41%, which belongs to the earliest (7 a.m.) class, so attendance was lowest for the earliest class — choice A. (B) reverses the comparison; 41% is the lowest, not the highest. (C) is false because the noon figure (68%) is below the evening figure (73%), not above it. (D) is contradicted by three clearly different percentages, so attendance was not equal." },
  { id: "t13rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The startup hired a designer ______ portfolio had won several national awards.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["who's", "whose", "whom", "which"], correct: 1, explanation: "The answer is (B) \"whose.\" The blank links \"a designer\" to \"portfolio,\" showing the portfolio belongs to the designer; this calls for the possessive relative pronoun \"whose.\" (A) \"who's\" is the contraction of \"who is\" — substitute it and you get \"who is portfolio,\" which is nonsense. (C) \"whom\" is an object pronoun and cannot show possession. (D) \"which\" refers to things, not people, so it cannot modify \"a designer.\" The trap is the sound-alike \"who's,\" which never signals possession." },
  { id: "t13rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Stepping off the boat after a month at sea, ______ the harbor town seemed almost dizzyingly loud to the sailor.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the harbor town seemed almost dizzyingly loud to the sailor", "the sailor found the harbor town almost dizzyingly loud", "almost dizzyingly loud was the harbor town to the sailor", "it seemed loud, the harbor town, to the sailor"], correct: 1, explanation: "The answer is (B). The introductory phrase \"Stepping off the boat after a month at sea\" is a participial modifier; the noun it modifies must come immediately after the comma and must be the one doing the stepping. Only the sailor can step off the boat, so the clause must begin with \"the sailor\" — choice B. (A) begins with \"the harbor town,\" illogically implying the town stepped off the boat. (C) begins with \"almost dizzyingly loud,\" again failing to name the stepper. (D) begins with \"it,\" which has no logical referent and leaves the modifier dangling. The rule: a leading participial phrase must attach to the subject that performs its action." },
  { id: "t13rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A researcher claims that classrooms painted in cool colors reduce student anxiety, leading to better test performance.", prompt: "Which finding, if true, would most strengthen the researcher's claim?", type: "mcq", choices: ["Students in cool-colored rooms scored higher and reported feeling calmer than those in warm-colored rooms.", "Cool colors are cheaper to apply than warm colors.", "Most schools already use cool colors.", "Test scores were identical across all room colors."], correct: 0, explanation: "The answer is (A). The claim has a chain: cool colors reduce anxiety, and lower anxiety improves test scores. A finding that strengthens it should support BOTH links. Choice A does exactly that — cool-room students both scored higher (the performance link) and reported feeling calmer (the anxiety link). (B) concerns the cost of paint, which is irrelevant to anxiety or scores. (C) concerns how common cool colors are, not their effect. (D) actually weakens the claim, since identical scores across colors would show color had no effect on performance." },
  { id: "t13rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with the lead actors, ______ rehearsing the final scene late into the night.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "are", "have been"], correct: 0, explanation: "The answer is (A) \"was.\" The subject is the singular \"director.\" A phrase introduced by \"together with\" (like \"as well as\" or \"along with\") is parenthetical — set off by commas — and does NOT join its noun to the subject to make it plural. So the verb stays singular: \"was.\" (B) \"were,\" (C) \"are,\" and (D) \"have been\" are all plural and wrongly treat \"the lead actors\" as part of the subject. The trap is the nearby plural \"actors\"; only a true compound subject joined by \"and\" would make the verb plural." },
  { id: "t13rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A geologist wants to underscore that two distant volcanoes erupted in the very same week. ______, both events occurred within a single seven-day span in March.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "The answer is (B) \"Remarkably.\" The setup states the geologist wants to underscore that two distant volcanoes erupted in the very same week — a striking coincidence. \"Remarkably\" adds exactly that note of wonder and emphasis. (A) \"By contrast\" and (C) \"However\" both signal opposition, but the two facts agree rather than conflict. (D) \"Otherwise\" introduces an alternative or what-would-happen-instead, which does not fit a statement meant to highlight a coincidence. Matching the transition to the writer's stated purpose (to underscore) points to the emphatic choice." },
  { id: "t13rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The treaty's wording was kept deliberately ______ so that each nation's negotiators could later interpret the key clause to their own advantage.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "explicit", "concise", "binding"], correct: 0, explanation: "Wording that lets each side read a clause to its own advantage must be open to multiple readings, that is, \"ambiguous.\" \"Explicit\" and \"binding\" would foreclose differing interpretations, and \"concise\" addresses length, not the openness of meaning the sentence describes." },
  { id: "t13rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate applies only to vehicles that emit below 90 grams of carbon dioxide per kilometer and that were purchased after January 2025.", prompt: "Which vehicle clearly qualifies for the rebate?", type: "mcq", choices: ["A car emitting 80 grams per kilometer bought in March 2025.", "A car emitting 120 grams per kilometer bought in March 2025.", "A car emitting 80 grams per kilometer bought in 2023.", "A car that was never purchased."], correct: 0, explanation: "Both conditions — under 90 grams and purchased after January 2025 — are met only by the 80-gram car bought in March 2025 (choice A). Choice B exceeds the emissions limit, choice C was bought before the cutoff, and choice D was never purchased at all." },
  { id: "t13rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the cracked hull ______ they refloated the ship at high tide.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["hull, and then", "hull and, then", "hull then", "hull, then"], correct: 0, explanation: "Two independent clauses must be joined by a comma plus a coordinating conjunction, which choice A supplies with \"and then.\" Choice B misplaces the comma, choice C creates a run-on with no conjunction, and choice D produces a comma splice." },
  { id: "t13rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although the inventor was famous for his ______ schemes, several of his wildest ideas eventually proved entirely workable.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["fanciful", "practical", "modest", "cautious"], correct: 0, explanation: "The contrast set up by \"Although … eventually proved workable\" implies the schemes first seemed \"fanciful\" (far-fetched). \"Practical,\" \"modest,\" and \"cautious\" would not create the contrast the sentence requires between an initial impression and the later workable result." },
  { id: "t13rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist observes that towns built along the new railway grew faster than nearby towns it bypassed, crediting the gap to cheaper shipping of goods.", prompt: "Which choice best describes the economist's explanation?", type: "mcq", choices: ["Cheaper shipping along the railway drove the faster growth of connected towns.", "Bypassed towns enjoyed cheaper shipping.", "The railway slowed the growth of towns along it.", "Town location had no effect on growth."], correct: 0, explanation: "The economist credits the growth gap to cheaper shipping enabled by the railway, which is choice A. Choice B reverses who benefited, choice C contradicts \"grew faster,\" and choice D denies the location effect the economist explicitly identifies." },
  { id: "t13rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The launch was postponed ______ the weather forecast warned of high winds along the coast.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["postponed because", "postponed, because", "postponed; because", "postponed: because"], correct: 0, explanation: "When a dependent \"because\" clause follows the main clause, no punctuation is needed before it, so choice A is correct. A comma (B) is unnecessary, while a semicolon (C) or colon (D) wrongly signals a break that the subordinating conjunction does not call for." },
  { id: "t13rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The clinic digitized its appointment system. ______, average patient wait times dropped from forty minutes to twelve.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The shorter wait times are the effect of digitizing the system, so the cause-and-effect transition \"As a result\" is correct. \"Nevertheless\" and \"On the other hand\" signal contrast, and \"For example\" introduces an illustration rather than a consequence." },
  { id: "t13rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach offered ______ feedback, pointing to the exact moment in the replay where the play broke down.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "vague", "general", "evasive"], correct: 0, explanation: "Pointing to an exact moment in the replay is the hallmark of \"specific\" feedback. \"Vague\" and \"general\" mean the opposite of pinpointed, and \"evasive\" implies avoiding the point rather than identifying it precisely." },
  { id: "t13rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "After beavers returned to the creek, their dams slowed the spring runoff, which raised the water table and let drought-stricken meadows green up again downstream.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The beavers' dams set off a chain of effects that revived nearby meadows.", "The beavers planted the meadow grasses themselves.", "The dams dried out the meadows downstream.", "The water table fell after the beavers returned."], correct: 0, explanation: "Dams slowed runoff, which raised the water table, which revived the meadows — a chain of effects, exactly choice A. Choice B misreads the indirect mechanism as direct planting, while choices C and D reverse the actual outcomes of greener meadows and a higher water table." },
];

// ─────────────────────── PRACTICE TEST 13 · R&W M2 easy (27) ─────────────────
const T13_RW_M2E: SatQuestion[] = [
  { id: "t13rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The juice was too ______, so I stirred in a spoonful of sugar.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["sour", "sweet", "cold", "purple"], correct: 0, explanation: "The answer is (A) \"sour.\" The logic of the sentence is cause and fix: a problem with the juice led the speaker to stir in sugar, and sugar makes things sweeter. The taste that sugar corrects is sourness, so \"sour\" fits the blank. (B) \"sweet\" is wrong because adding sugar to already-sweet juice would make the problem worse, not solve it. (C) \"cold\" describes temperature, which a spoonful of sugar does nothing to change. (D) \"purple\" describes color, which sugar also cannot fix. Only \"sour\" names a taste that stirring in sugar would actually remedy." },
  { id: "t13rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three puppies ______ playing in the yard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) \"are.\" This tests subject-verb agreement. The subject is \"three puppies,\" which is plural, so it requires the plural present-tense verb \"are\" (the puppies ARE playing). (A) \"is\" is singular and would only fit a singular subject like \"one puppy.\" (C) \"was\" is singular and also shifts to the past tense, neither of which matches a plural subject in the present. (D) \"am\" is used only with the first-person pronoun \"I,\" never with a third-person plural noun. Only \"are\" agrees in both number and person." },
  { id: "t13rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bees carry pollen from flower to flower, which helps many plants produce fruits and seeds.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees help plants reproduce by moving pollen between flowers.", "Bees keep plants from making seeds.", "Bees never visit flowers.", "Plants make fruit without any help."], correct: 0, explanation: "The answer is (A). The text says bees carry pollen from flower to flower, \"which helps many plants produce fruits and seeds\" — that is, bees help plants reproduce by moving pollen, exactly choice A. (B) reverses the bees' role: the text says they help plants make seeds, not keep them from doing so. (C) is contradicted by \"from flower to flower,\" which shows bees do visit flowers. (D) ignores the central point of the sentence, which is that the plants' fruit-and-seed production depends on the bees' help, so it is not \"without any help.\"" },
  { id: "t13rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The movie was about to start. ______, we hurried to find our seats.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The answer is (B) \"So.\" The first sentence gives a cause — the movie was about to start — and the second gives the effect: we hurried to our seats. \"So\" signals that cause-and-effect link. (A) \"For example\" introduces an illustration of a general point, but hurrying is a consequence, not an example. (C) \"However\" signals contrast, yet there is no opposition between the movie starting and hurrying. (D) \"Meanwhile\" marks two unrelated events happening at the same time, but here one event causes the other. Only \"So\" expresses the result relationship the sentences require." },
  { id: "t13rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night the children ______ a sandcastle at the beach.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["build", "builds", "built", "building"], correct: 2, explanation: "The answer is (C) \"built.\" The time marker \"Last night\" places the action in the past, so the main verb must be the past tense \"built.\" (A) \"build\" is the present-tense plural form and ignores the past-time signal. (B) \"builds\" is the present-tense singular form, which is both the wrong tense and wrong in number for the plural subject \"children.\" (D) \"building\" is a present participle that needs a helping verb (such as \"were building\") and cannot serve as the main verb by itself. Only \"built\" matches the past time frame the sentence sets up." },
  { id: "t13rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puzzle was so ______ that she solved it in under a minute.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["easy", "hard", "heavy", "loud"], correct: 0, explanation: "The answer is (A) \"easy.\" The \"so ______ that…\" structure links the puzzle's quality to its result: she solved it in under a minute. Solving a puzzle that fast shows it was easy. (B) \"hard\" is the opposite; a hard puzzle would take a long time, not under a minute. (C) \"heavy\" describes weight, which has nothing to do with how quickly a puzzle is solved. (D) \"loud\" describes sound, also irrelevant to difficulty. Only \"easy\" produces a cause-and-result that fits the quick solution." },
  { id: "t13rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money on gas, gives you exercise, and reduces traffic.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is dangerous.", "Walking to school costs more money.", "Walking to school causes traffic."], correct: 0, explanation: "The answer is (A). The text lists three good things about walking to school: it saves money on gas, gives you exercise, and reduces traffic. Together these are several benefits, which is exactly what choice A says. (B) \"dangerous\" appears nowhere in the text and contradicts the positive tone. (C) is refuted by \"saves money on gas\"; walking costs less, not more. (D) reverses a stated benefit — the text says walking \"reduces traffic,\" not that it causes it. Only A captures the list of advantages as a whole." },
  { id: "t13rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He waited for ______ apple to ripen before picking it.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the most", "some"], correct: 1, explanation: "The answer is (B) \"an.\" The rule is that \"an\" comes before a word beginning with a vowel sound and \"a\" before a consonant sound. \"Apple\" starts with the vowel sound /a/, so \"an apple\" is correct. (A) \"a\" is used before consonant sounds, so \"a apple\" is wrong. (C) \"the most\" is a superlative phrase that needs something to compare and does not fit a single ripening apple. (D) \"some\" signals an unspecified quantity or plural, but the sentence refers to one specific apple. Only \"an\" fits the singular vowel-sound noun." },
  { id: "t13rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was too ______, so she took out some of the books.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "empty", "small"], correct: 0, explanation: "The answer is (A) \"heavy.\" The \"too ______, so…\" structure links the problem to the fix: she took out some books. Removing books reduces weight, so the problem was that the backpack was too heavy. (B) \"light\" is the opposite; you would not remove books from an already-light bag. (C) \"empty\" is impossible, since an empty backpack would have no books to take out. (D) \"small\" describes size, but removing books changes weight, not the size of the backpack. Only \"heavy\" matches the action of taking books out." },
  { id: "t13rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My friends and I ______ meeting at the park after lunch.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) \"are.\" The subject is the compound \"my friends and I,\" and two subjects joined by \"and\" form a plural subject, which takes the plural verb \"are.\" (A) \"is\" and (C) \"was\" are both singular and cannot agree with a plural subject. (D) \"am\" is correct only when the subject is \"I\" by itself; once \"I\" is joined to \"my friends,\" the subject becomes plural and \"am\" no longer fits. Only \"are\" agrees with the plural compound subject." },
  { id: "t13rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Polar bears have a thick layer of fat and dense fur that keep them warm in freezing weather.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Fat and fur help polar bears stay warm in the cold.", "Polar bears are always cold.", "Polar bears have no fur.", "Polar bears live in hot deserts."], correct: 0, explanation: "The answer is (A). The text states that a thick layer of fat and dense fur \"keep them warm in freezing weather,\" so the main idea is that fat and fur help polar bears stay warm in the cold — choice A. (B) contradicts the point: the adaptations keep the bears warm, so they are not \"always cold.\" (C) is directly refuted by \"dense fur.\" (D) misplaces the habitat; the freezing weather described is the opposite of a hot desert. Only A states the main idea the sentence supports." },
  { id: "t13rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, we lit candles to see.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "So", "For example", "Instead"], correct: 1, explanation: "The answer is (B) \"So.\" The first sentence is the cause — the power went out — and the second is the effect: we lit candles to see. \"So\" signals that result relationship. (A) \"However\" signals contrast, but lighting candles agrees with, rather than opposes, losing power. (C) \"For example\" introduces an illustration of a general claim, which is not what the second sentence does. (D) \"Instead\" signals a replacement or alternative to something rejected, but nothing here is being rejected. Only \"So\" expresses cause and effect." },
  { id: "t13rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the baker ______ a fresh batch of bread before dawn.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["bake", "bakes", "baked", "baking"], correct: 2, explanation: "The answer is (C) \"baked.\" The time marker \"Yesterday\" places the action in the past, so the main verb must be the past tense \"baked.\" (A) \"bake\" is present-tense plural and clashes with both the past-time signal and the singular subject \"baker.\" (B) \"bakes\" is present-tense singular; it agrees in number but is the wrong tense for a past action. (D) \"baking\" is a present participle that needs a helping verb (such as \"was baking\") and cannot stand alone as the main verb. Only \"baked\" fits the past time frame." },
  { id: "t13rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After the long hike, the campers were ______ and went straight to sleep.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "alert", "hungry", "cheerful"], correct: 0, explanation: "The answer is (A) \"tired.\" The sentence pairs the cause (a long hike) with the result (the campers went straight to sleep). Going immediately to sleep is what tired people do, so \"tired\" fits. (B) \"alert\" is the opposite of sleepy; alert people would not head straight to bed. (C) \"hungry\" would more likely lead to eating than to sleeping. (D) \"cheerful\" describes a mood and does not explain why they fell asleep at once. Only \"tired\" gives a logical reason for going straight to sleep." },
  { id: "t13rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from June through August but closes for the rest of the year.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The pool is closed in December.", "The pool is open all year.", "The pool opens only in winter.", "The pool never opens."], correct: 0, explanation: "The answer is (A). The text says the pool is open June through August and \"closes for the rest of the year.\" December falls outside June–August, so it is part of \"the rest of the year\" and the pool is closed then — choice A. (B) contradicts the text, which says the pool closes for much of the year. (C) names winter, but the pool is open in summer, not winter. (D) ignores the stated June-through-August opening. Only A follows directly from the given schedule." },
  { id: "t13rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after the meal.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The answer is (A) \"its.\" The blank shows possession — the paws belong to the cat — and \"cat\" is singular, so the singular possessive pronoun \"its\" (no apostrophe) is correct. (B) \"it's\" is the contraction of \"it is\"; substitute it and you get \"licked it is paws,\" which is nonsense. (C) \"their\" is a plural possessive and cannot refer to a single cat. (D) \"they're\" means \"they are,\" again producing \"licked they are paws.\" The trap is the sound-alike \"it's,\" which is never possessive; only \"its\" shows possession." },
  { id: "t13rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Many animals sleep during the day. ______, owls hunt at night and rest while the sun is up.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is (A) \"For example.\" The first sentence makes a general claim — many animals sleep during the day — and the second names owls, which rest while the sun is up, as a specific instance of that claim. \"For example\" introduces exactly that illustration. (B) \"However\" and (C) \"Instead\" both signal contrast, but the owl agrees with the general point rather than opposing it. (D) \"Otherwise\" introduces what would happen under a different condition, which does not fit an illustrating example. Only \"For example\" matches the general-to-specific move." },
  { id: "t13rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The classroom was very ______, so the teacher asked everyone to lower their voices.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["noisy", "quiet", "empty", "dark"], correct: 0, explanation: "The answer is (A) \"noisy.\" The \"so ______, so…\" structure links the room's state to the teacher's response: she asked everyone to lower their voices. A teacher makes that request when the room is too loud, so \"noisy\" fits. (B) \"quiet\" is the opposite; a quiet room needs no request to lower voices. (C) \"empty\" makes no sense, since an empty room has no voices to lower. (D) \"dark\" concerns light, not sound, and would not prompt a request about voices. Only \"noisy\" explains the teacher's reaction." },
  { id: "t13rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The keys ______ hanging on the hook by the door.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) \"are.\" The subject is the plural noun \"keys,\" so it takes the plural present-tense verb \"are\" (the keys ARE hanging). (A) \"is\" is singular and would fit only a singular subject like \"the key.\" (C) \"was\" is singular and also past tense, neither matching a plural present-tense subject. (D) \"am\" is used only with the pronoun \"I.\" The trap is letting \"hook\" or \"door\" near the verb mislead you; the true subject is the plural \"keys,\" so \"are\" is correct." },
  { id: "t13rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Turtles can pull their heads and legs inside their hard shells to stay safe from predators.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["A turtle's shell protects it from predators.", "Turtles have no shells.", "Turtles cannot move their heads.", "Predators always catch turtles."], correct: 0, explanation: "The answer is (A). The text says turtles can pull their heads and legs inside their hard shells \"to stay safe from predators,\" so the main idea is that the shell protects the turtle from predators — choice A. (B) is directly refuted by \"their hard shells.\" (C) overstates the point: the text says turtles pull their heads in by choice, not that they cannot move them. (D) contradicts the protection the shell provides; the passage stresses staying safe, not always being caught. Only A states the main idea." },
  { id: "t13rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned a picnic for Saturday. ______, it rained all day.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "The answer is (A) \"However.\" The first sentence sets up an expectation — we planned a picnic — and the second reverses it: it rained all day, ruining the plan. That opposition calls for the contrast word \"However.\" (B) \"Therefore\" signals a result, but rain is not a consequence of planning a picnic. (C) \"For example\" introduces an illustration, which the rain is not. (D) \"Similarly\" signals likeness, yet the two sentences clash rather than agree. Only \"However\" marks the contrast between the plan and the disappointing weather." },
  { id: "t13rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month our class ______ to visit the science museum.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The answer is (B) \"plans.\" The subject is the singular collective noun \"class,\" which takes the singular present-tense verb \"plans,\" and the simple present can express a scheduled future action with \"next month.\" (A) \"plan\" is the plural form and does not agree with the singular \"class.\" (C) \"planned\" is past tense, which clashes with the future signal \"next month.\" (D) \"planning\" is a participle that needs a helping verb (such as \"is planning\") and cannot serve as the main verb alone. Only \"plans\" agrees in number and works with the future reference." },
  { id: "t13rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The road was very ______, so the driver slowed down to stay safe.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["icy", "smooth", "wide", "straight"], correct: 0, explanation: "The answer is (A) \"icy.\" The sentence links the road's condition to the driver's response: the driver slowed down to stay safe. A driver slows for a dangerous surface, and an icy road is slippery and hazardous, so \"icy\" fits. (B) \"smooth,\" (C) \"wide,\" and (D) \"straight\" all describe easy, safe driving conditions that would not require slowing down for safety. Only \"icy\" gives a logical reason to drive more cautiously." },
  { id: "t13rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Eating fruits and vegetables gives your body vitamins, fiber, and energy.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Fruits and vegetables provide several things the body needs.", "Fruits and vegetables are unhealthy.", "Fruits and vegetables have no nutrients.", "Only fruit gives the body energy."], correct: 0, explanation: "The answer is (A). The text says eating fruits and vegetables gives the body vitamins, fiber, and energy — three things the body needs — so the main idea is that produce provides several beneficial things, choice A. (B) \"unhealthy\" contradicts the clearly positive list. (C) is refuted because vitamins and fiber are nutrients, so they do not have \"no nutrients.\" (D) wrongly singles out fruit, but the sentence credits both fruits and vegetables with providing energy. Only A captures the full list of benefits." },
  { id: "t13rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She wore ______ orange scarf to match her hat.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the most", "some"], correct: 1, explanation: "The answer is (B) \"an.\" The rule is \"an\" before a vowel sound and \"a\" before a consonant sound. \"Orange\" begins with the vowel sound /o/, so \"an orange scarf\" is correct. (A) \"a\" is for consonant sounds, so \"a orange\" is wrong. (C) \"the most\" is a superlative that needs a comparison and does not fit a single scarf. (D) \"some\" suggests an unspecified or plural amount, but the sentence describes one specific scarf. Only \"an\" fits the singular vowel-sound noun." },
  { id: "t13rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The directions were clear and short. ______, the project took only an hour to finish.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is (A) \"In addition.\" The first sentence gives one favorable fact (the directions were clear and short) and the second gives a related favorable result (the project took only an hour). Because both point the same positive direction, the additive transition \"In addition\" fits. (B) \"However\" and (C) \"Instead\" both signal contrast, but the two facts agree rather than oppose. (D) \"Otherwise\" introduces what would happen under a different condition, which does not match two stacked positives. Only \"In addition\" adds the second point to the first." },
  { id: "t13rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the rabbit disappear.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "The answer is (A) \"amazed.\" A magician making a rabbit disappear is a surprising, impressive feat, and the natural audience reaction to such a trick is wonder, which \"amazed\" names. (B) \"bored\" and (C) \"sleepy\" describe a lack of interest, the opposite of reacting to an exciting trick. (D) \"angry\" describes displeasure, which an entertaining illusion would not normally cause. Only \"amazed\" matches the audience's likely response to a striking magic trick." },
];

// ─────────────────────── PRACTICE TEST 13 · R&W M2 hard (27) ─────────────────
const T13_RW_M2H: SatQuestion[] = [
  { id: "t13rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic's praise was so ______ that readers could not tell whether she admired the film or merely tolerated it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["tepid", "effusive", "scathing", "precise"], correct: 0, explanation: "The answer is (A) \"tepid.\" The result clause is the key: the praise was so ______ that readers could not tell whether she admired the film or merely tolerated it. Praise that blurs admiration into mere tolerance must be lukewarm and unenthusiastic, which is exactly what \"tepid\" means. (B) \"effusive\" means gushing and overflowing with enthusiasm — that would make her admiration unmistakable, not unclear. (C) \"scathing\" means harshly critical, but the word being modified is \"praise,\" so a harsh sense contradicts the sentence. (D) \"precise\" means exact and clear, which would let readers tell her view easily, the opposite of the confusion described. Only \"tepid\" produces praise faint enough to be mistaken for mere tolerance." },
  { id: "t13rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The chapter opens with a sweeping claim about human nature, then narrows to a single case study that tests, and ultimately qualifies, that claim.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from a broad generalization to a specific case that complicates it.", "It lists unrelated facts with no organizing idea.", "It repeats one example without any claim.", "It states a conclusion and offers no support."], correct: 0, explanation: "The answer is (A). The text describes a clear structure: it \"opens with a sweeping claim about human nature\" (a broad generalization), then \"narrows to a single case study that tests, and ultimately qualifies, that claim\" (a specific case that complicates it). Choice A names exactly this general-to-specific, qualifying movement. (B) is wrong because the text has a clear organizing idea — the sweeping claim — not unrelated facts. (C) is wrong because there is a central claim, and the case study is not mere repetition. (D) is wrong because the text does offer support and qualification through the case study, rather than a bare, unsupported conclusion." },
  { id: "t13rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A solar panel produced 95% of its rated output in its first year, 93% after five years, and 80% after twenty years.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Output declined more steeply between years five and twenty than in the first five years.", "Output rose over the twenty-year period.", "Output stayed exactly constant.", "The panel produced nothing after five years."], correct: 0, explanation: "The answer is (A). Track the three figures: 95% at year one, 93% at year five, 80% at year twenty. From year one to five output fell only 2 points (95 to 93) across about four years, but from year five to twenty it fell 13 points (93 to 80) across fifteen years — and even per year the later drop (about 0.87 points/year) is steeper than the early drop (about 0.5 points/year). That steeper later decline is choice A. (B) reverses the trend; output fell, not rose. (C) is contradicted by the changing percentages, so output was not constant. (D) is false because the panel still produced 80% of its rated output at twenty years, well after year five." },
  { id: "t13rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The merger promised lower prices for consumers. ______, it would hand a single company control over nearly the entire market.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Yet", "Likewise", "Accordingly"], correct: 1, explanation: "The answer is (B) \"Yet.\" The first sentence states a benefit of the merger (lower prices for consumers) and the second states a serious downside (handing one company control of nearly the whole market). A benefit set against a drawback calls for a contrast word, and \"Yet\" provides it. (A) \"Therefore\" and (D) \"Accordingly\" both signal a consequence, but near-monopoly is not a result of lower prices; the two are opposing considerations. (C) \"Likewise\" signals similarity, yet the two facts pull in opposite directions. Only \"Yet\" captures the tension between the promised benefit and the hidden cost." },
  { id: "t13rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches students to analyze data, to write reports, and ______ findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "The answer is (A) \"to present.\" The rule is parallel structure: items in a series must share the same grammatical form. The list here is \"to analyze data, to write reports, and ______ findings,\" and the first two items are infinitives (\"to analyze,\" \"to write\"), so the third must also be the infinitive \"to present.\" (B) \"presenting\" is a gerund, which breaks the infinitive pattern. (C) \"present\" is a bare verb form, also out of parallel with the \"to + verb\" items. (D) \"presented\" is past tense and likewise does not match. Only \"to present\" keeps the three-item series parallel." },
  { id: "t13rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The historian refuses to ______ the era, presenting its injustices as plainly as its achievements.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["romanticize", "condemn", "ignore", "record"], correct: 0, explanation: "The answer is (A) \"romanticize.\" The clue is that the historian presents the era's injustices \"as plainly as its achievements\" — a balanced, unflinching view. To refuse to romanticize means refusing to idealize or gloss over the era, which is exactly what showing the injustices plainly accomplishes. (B) \"condemn\" means to denounce, but presenting achievements just as plainly shows the historian is not one-sidedly negative. (C) \"ignore\" contradicts the text, since the historian actually presents the injustices rather than overlooking them. (D) \"record\" is something the historian does, not something refused, so \"refuses to record\" would contradict the balanced presentation. Only \"romanticize\" fits the refusal to prettify the past." },
  { id: "t13rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats the famine as a sudden natural disaster, the revisionist account frames it as the predictable result of years of policy choices.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast a traditional explanation of a famine with a revisionist one.", "To prove the famine never happened.", "To summarize only the traditional account.", "To argue that policy had no role."], correct: 0, explanation: "The answer is (A). The sentence is built on the frame \"Where the traditional account treats the famine as a sudden natural disaster, the revisionist account frames it as the predictable result of … policy choices.\" That \"Where X, Y\" structure sets one explanation against the other, so the purpose is to contrast a traditional and a revisionist explanation — choice A. (B) is wrong because the text discusses how to explain the famine, never denying it occurred. (C) is wrong because the text gives both accounts, not only the traditional one. (D) contradicts the revisionist view, which explicitly attributes the famine to policy choices. Only A captures the contrasting purpose." },
  { id: "t13rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The first draft sailed through review ______ the revised version raised objections from nearly every editor.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["review, the", "review; the", "review the", "review: the"], correct: 1, explanation: "The answer is (B) \"review; the\" (semicolon). Both halves are independent clauses: \"The first draft sailed through review\" and \"the revised version raised objections from nearly every editor.\" Two independent clauses with no coordinating conjunction between them are correctly joined by a semicolon. (A) a comma creates a comma splice, illegally joining two complete sentences with only a comma. (C) no punctuation produces a run-on (fused) sentence. (D) a colon would wrongly signal that the second clause explains or completes the first, but here the clauses are two equal, contrasting statements. Only the semicolon correctly links them." },
  { id: "t13rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the report's conclusions were hedged with so many qualifications that no firm recommendation emerged.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["decisive", "tentative", "cautious", "vague"], correct: 0, explanation: "The answer is (A) \"decisive.\" The phrase \"Far from being ______\" requires a word that is the OPPOSITE of what the conclusions actually were. The conclusions \"were hedged with so many qualifications that no firm recommendation emerged\" — that is, they were anything but firm. The opposite of that hedged state is \"decisive,\" so the report was far from decisive. (B) \"tentative,\" (C) \"cautious,\" and (D) \"vague\" all describe the hedged, qualification-laden conclusions themselves; plugging any of them in would say the report was far from being hedged, which contradicts the rest of the sentence. Only \"decisive\" provides the needed opposite." },
  { id: "t13rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Supporters insist the program lifted reading scores. Yet in the districts that adopted it, scores had already been rising for three years before it began.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It introduces evidence that questions the supporters' causal claim.", "It restates the supporters' claim word for word.", "It confirms the program caused the gains.", "It proposes a completely new program."], correct: 0, explanation: "The answer is (A). Supporters claim the program lifted reading scores; the second sentence, opening with \"Yet,\" notes that scores \"had already been rising for three years before it began.\" If scores were already climbing before the program started, the program may not be the cause — so the sentence introduces evidence that questions the supporters' causal claim, choice A. (B) is wrong because the sentence adds new information rather than restating the claim. (C) is the opposite of what \"Yet\" does; the sentence undercuts the causal claim rather than confirming it. (D) is wrong because no new program is proposed. Only A names the doubt-raising function." },
  { id: "t13rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The recipe depends on three pantry staples ______ olive oil, sea salt, and crushed garlic.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["staples,", "staples:", "staples;", "staples"], correct: 1, explanation: "The answer is (B) \"staples:\" (colon). The clause before the blank, \"The recipe depends on three pantry staples,\" is grammatically complete and independent, and what follows specifies those staples: olive oil, sea salt, and crushed garlic. A colon is the correct mark to introduce a list after a complete clause. (A) a comma is too weak to formally introduce the explanatory list. (C) a semicolon must join two independent clauses, but \"olive oil, sea salt, and crushed garlic\" is a list, not an independent clause. (D) no punctuation leaves the list running into the clause unmarked. Only the colon properly introduces the naming list." },
  { id: "t13rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine produced strong antibody levels in the trial. ______, those levels faded within four months, raising questions about booster shots.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "However", "Therefore", "Likewise"], correct: 1, explanation: "The answer is (B) \"However.\" The first sentence reports a positive result — the vaccine produced strong antibody levels — and the second reverses it: those levels faded within four months. A positive outcome followed by its undoing calls for a contrast word, so \"However\" fits. (A) \"Indeed\" intensifies or confirms a prior point, but the fading antibodies do not reinforce the strong result; they cut against it. (C) \"Therefore\" signals a consequence, yet the fading is not a result caused by the strong levels. (D) \"Likewise\" signals similarity, but the two facts oppose each other. Only \"However\" marks the reversal." },
  { id: "t13rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a controlled trial, the new coating made the metal 40% more resistant to corrosion, but it also increased the metal's brittleness by 25%.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The coating improved corrosion resistance but reduced durability under stress.", "The coating improved both corrosion resistance and flexibility.", "The coating had no measurable effect.", "Uncoated metal resisted corrosion better than coated metal."], correct: 0, explanation: "The answer is (A). The data give two effects: corrosion resistance rose 40% (a benefit) and brittleness rose 25% (a downside, since brittle metal is more likely to crack under stress). So the coating improved corrosion resistance but reduced durability under stress — choice A. (B) is wrong because increased brittleness is the opposite of flexibility, so the coating did not improve flexibility. (C) ignores the two clearly measured 40% and 25% changes. (D) reverses the corrosion finding; the coated metal resisted corrosion better, not worse. Only A reflects both measured effects accurately." },
  { id: "t13rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The bridge that connects the two island villages ______ been closed for repairs since the storm.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["have", "has", "having", "to have"], correct: 1, explanation: "The answer is (B) \"has.\" This tests subject-verb agreement across an intervening relative clause. The subject is the singular \"bridge\"; the words \"that connects the two island villages\" form a relative clause whose plural \"villages\" is not the subject. A singular subject takes the singular auxiliary \"has\" (the bridge HAS been closed). (A) \"have\" is plural and wrongly agrees with the nearby \"villages\" instead of \"bridge.\" (C) \"having\" and (D) \"to have\" are non-finite forms (participle and infinitive) that cannot serve as the main verb of the sentence. The trap is matching the verb to the closest noun rather than to the true subject." },
  { id: "t13rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor valued the writer's ______ — her habit of cutting any sentence that did not earn its place.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["rigor", "negligence", "verbosity", "hesitation"], correct: 0, explanation: "The answer is (A) \"rigor.\" The dash introduces a definition of the blank: \"her habit of cutting any sentence that did not earn its place.\" Strictly removing every unjustified sentence is a disciplined, exacting practice, which is what \"rigor\" names. (B) \"negligence\" means carelessness, the opposite of carefully cutting weak sentences. (C) \"verbosity\" means wordiness — the very fault the writer eliminates, so it cannot be the quality the editor valued. (D) \"hesitation\" means doubt or holding back, which does not describe a decisive habit of cutting. Only \"rigor\" matches the disciplined trimming the editor praises." },
  { id: "t13rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that early telescopes were crude and gave blurry images, then argues that these very flaws pushed astronomers to invent the precise lenses that revolutionized the field.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It recasts an apparent weakness as the spur for later progress.", "It denies that early telescopes had any limitations.", "It claims telescopes never improved.", "It lists the prices of telescopes over time."], correct: 0, explanation: "The answer is (A). The author concedes a weakness — early telescopes were crude and gave blurry images — then argues that \"these very flaws pushed astronomers to invent the precise lenses that revolutionized the field.\" That turns the apparent weakness into the very thing that spurred progress, exactly choice A. (B) is wrong because the author admits the flaws rather than denying them. (C) is wrong because the text describes a revolution in the field, the opposite of never improving. (D) introduces prices, which the text never mentions. Only A captures the weakness-into-catalyst reasoning." },
  { id: "t13rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having studied the ancient script for decades ______ the linguist immediately recognized the carving's hidden meaning.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the carving's hidden meaning was clear", "the linguist immediately recognized the carving's hidden meaning", "it was clear, the carving's meaning", "clear was the hidden meaning of the carving"], correct: 1, explanation: "The answer is (B). The opening phrase \"Having studied the ancient script for decades\" is a participial modifier, and the noun right after the comma must be the one who did the studying. Only a person can study a script for decades, so the main clause must begin with \"the linguist\" — choice B. (A) begins with \"the carving's hidden meaning,\" illogically implying the meaning studied the script. (C) begins with \"it,\" which has no logical referent for the studying. (D) begins with \"clear,\" again failing to name the studier and leaving the modifier dangling. The rule: a leading participial phrase must attach to the subject that performs its action." },
  { id: "t13rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The compound killed the bacteria in a petri dish. ______, it proved far less effective once tested inside living tissue.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In living tissue, however", "For this reason", "Similarly"], correct: 1, explanation: "The answer is (B) \"In living tissue, however.\" The first sentence reports success in a petri dish; the second reports that the compound \"proved far less effective once tested inside living tissue.\" That is a contrast, and \"however\" supplies it while the phrase \"In living tissue\" pinpoints the new setting. (A) \"Consequently\" and (C) \"For this reason\" both signal a consequence, but the weak result is not caused by the dish success; it opposes it. (D) \"Similarly\" signals likeness, yet the two outcomes differ sharply. Only choice B both marks the contrast and identifies the changed condition." },
  { id: "t13rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The architect praised the building's ______ design, in which a single arch motif reappears, subtly varied, in every room.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "chaotic", "random", "clashing"], correct: 0, explanation: "The answer is (A) \"cohesive.\" The detail after the blank explains it: \"a single arch motif reappears, subtly varied, in every room.\" One motif repeated throughout ties the whole building together into a unified design, which is what \"cohesive\" means, and the architect's praise confirms a positive quality. (B) \"chaotic,\" (C) \"random,\" and (D) \"clashing\" all describe disorder or disunity — the opposite of a single recurring motif that unifies the rooms, and none would earn praise. Only \"cohesive\" matches a unifying, repeated design element." },
  { id: "t13rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across six clinics, those that added evening appointment slots saw missed-appointment rates fall by an average of 22%, while clinics that kept daytime-only hours saw no change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding evening slots was associated with fewer missed appointments.", "Daytime-only hours reduced missed appointments.", "Appointment hours had no relationship to missed appointments.", "All clinics kept the same hours."], correct: 0, explanation: "The answer is (A). The data say clinics that added evening slots saw missed-appointment rates fall by an average of 22%, while clinics that kept daytime-only hours saw no change. So adding evening slots was associated with fewer missed appointments — choice A. (B) is wrong because the daytime-only clinics saw \"no change,\" so those hours did not reduce missed appointments. (C) is contradicted by the clear difference between the two groups, which shows hours did relate to attendance. (D) is false because some clinics added evening slots, so not all kept the same hours. Note that choice A is carefully worded as an association, which is exactly what the observational data support." },
  { id: "t13rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The composer's early symphonies — bold, restless, and unmistakably modern ______ already hinted at the style that would later make her famous.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["symphonies —", "symphonies,", "symphonies", "symphonies;"], correct: 0, explanation: "The answer is (A) \"symphonies —\" (closing dash). The phrase \"bold, restless, and unmistakably modern\" is a nonessential interrupter set off by a dash earlier in the sentence, and a dash that opens such an aside must be matched by a dash that closes it. So a second dash is required after \"symphonies.\" (B) a comma, (C) no punctuation, and (D) a semicolon all fail to match the opening dash, leaving the interrupting description improperly closed. The rule: paired punctuation around an interrupter must be the same type on both sides, so dash must answer dash." },
  { id: "t13rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Officials dismissed the engineer's warning as ______, only to see the predicted crack appear in the dam within a year.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["overblown", "prophetic", "valid", "urgent"], correct: 0, explanation: "The answer is (A) \"overblown.\" The structure \"dismissed … as ______, only to see the predicted crack appear\" requires a word that names how the officials wrongly downplayed the warning. To dismiss a warning is to treat it as exaggerated, which \"overblown\" means, and the crack later appearing shows they were mistaken. (B) \"prophetic\" and (C) \"valid\" describe a warning that proves true — but officials would not dismiss a warning they considered accurate, so these contradict \"dismissed.\" (D) \"urgent\" is also not a reason to dismiss something; an urgent warning would prompt action, not dismissal. Only \"overblown\" fits the act of wrongly brushing the warning aside." },
  { id: "t13rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One economist blames the recession on rising interest rates; another points to falling consumer confidence. A third contends that each factor amplified the other.", prompt: "Which choice best describes the third economist's position?", type: "mcq", choices: ["The two proposed causes intensified each other to deepen the recession.", "Neither interest rates nor confidence mattered.", "Only interest rates were responsible.", "There was no recession at all."], correct: 0, explanation: "The answer is (A). The first two economists each name a single cause (rising interest rates; falling consumer confidence). The third \"contends that each factor amplified the other,\" meaning the two causes intensified one another to worsen the recession — exactly choice A. (B) is wrong because saying each factor amplified the other affirms that both mattered, not that neither did. (C) is wrong because the third economist invokes both causes, not interest rates alone. (D) is wrong because all three economists are explaining a recession, so none denies it occurred. Only A captures the mutual-amplification position." },
  { id: "t13rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The team rebuilt the prototype from scratch ______ the original had overheated during every stress test.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["scratch, the", "scratch; the", "scratch the", "scratch: the"], correct: 1, explanation: "The answer is (B) \"scratch; the\" (semicolon). Both halves are independent clauses: \"The team rebuilt the prototype from scratch\" and \"the original had overheated during every stress test.\" With no coordinating conjunction between them, a semicolon is the correct mark to join two complete clauses. (A) a comma creates a comma splice. (C) no punctuation makes a run-on (fused) sentence. (D) a colon wrongly signals that the second clause merely explains or completes the first, but here the two clauses are equal statements (cause and action) rather than an introduction and its elaboration. Only the semicolon links them correctly." },
  { id: "t13rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the reform's costs fell unevenly. ______, small farmers paid steep new fees while large agribusinesses were exempted.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The answer is (A) \"Specifically.\" The first sentence makes a general claim — the reform's costs fell unevenly — and the second gives the concrete details that prove it: small farmers paid steep new fees while large agribusinesses were exempted. Moving from a general point to its specific illustration calls for \"Specifically.\" (B) \"In contrast\" and (C) \"Nevertheless\" signal opposition, but the second sentence supports the first rather than opposing it. (D) \"Otherwise\" introduces an alternative condition, which does not fit an illustration. Only \"Specifically\" matches the general-to-specific move." },
  { id: "t13rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Instead of tidying the ending, the filmmaker leaves the protagonist's fate ______, inviting viewers to debate it long after the credits roll.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["uncertain", "settled", "obvious", "fixed"], correct: 0, explanation: "The answer is (A) \"uncertain.\" The contrast \"Instead of tidying the ending\" plus the result \"inviting viewers to debate it long after the credits roll\" shows the filmmaker leaves the outcome open. A fate viewers can still debate is unresolved, which \"uncertain\" captures. (B) \"settled,\" (C) \"obvious,\" and (D) \"fixed\" all describe a clearly resolved ending — but if the fate were resolved, there would be nothing left to debate, contradicting the sentence. Only \"uncertain\" creates the open ending that invites ongoing debate." },
  { id: "t13rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author admits her survey reached only one neighborhood, but she argues that the pattern she found was so pronounced that it justifies a citywide study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["She acknowledges a limitation while defending the result's significance.", "She claims her survey covered the whole city.", "She abandons her finding entirely.", "She argues no further study is warranted."], correct: 0, explanation: "The answer is (A). The author \"admits her survey reached only one neighborhood\" — that is the acknowledged limitation — \"but she argues that the pattern she found was so pronounced that it justifies a citywide study,\" which defends the result's significance. That concede-then-defend move is exactly choice A. (B) contradicts the admission that the survey covered only one neighborhood. (C) is wrong because she does not abandon the finding; she defends it. (D) is the opposite of her actual point, since she calls for a citywide study. Only A captures both the concession and the defense." },
];

// ─────────────────────── PRACTICE TEST 13 · MATH M1 (22) ─────────────────────
const T13_M_M1: SatQuestion[] = [
  { id: "t13m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x − 8 = 27, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: isolate x. Add 8 to both sides to undo the subtraction: 5x = 35. Divide both sides by 5: x = 7. Check by substituting: 5(7) − 8 = 35 − 8 = 27, which matches, so x = 7." },
  { id: "t13m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 2 cups of rice for every 6 servings. How many cups are needed for 15 servings?", type: "mcq", choices: ["5", "4", "6", "3"], correct: 0, explanation: "Goal: scale the rice to 15 servings. The unit rate is 2 cups ÷ 6 servings = 1/3 cup per serving. Multiply by 15 servings: (1/3)(15) = 5 cups. A common trap is to scale only to 12 servings (4 cups); the question asks for 15." },
  { id: "t13m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² − 4, what is the value of f(2)?", type: "mcq", choices: ["8", "2", "32", "20"], correct: 0, explanation: "Goal: evaluate f at x = 2. Substitute: f(2) = 3(2²) − 4. Apply the exponent first: 2² = 4, so 3(4) − 4 = 12 − 4 = 8. The trap is squaring after multiplying (treating it as (3·2)² = 36); order of operations requires squaring the 2 before multiplying by 3." },
  { id: "t13m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 18. What is its radius?", type: "mcq", choices: ["9", "36", "18", "6"], correct: 0, explanation: "Goal: find the radius from the diameter. The radius is half the diameter: r = 18 ÷ 2 = 9. A trap is doubling instead of halving (giving 36); the radius is always smaller than the diameter, so 9 is correct." },
  { id: "t13m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 5x − 3 passes through the point (2, k). What is the value of k?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find the y-value when x = 2. Substitute x = 2 into the equation: k = 5(2) − 3. Compute: 5(2) = 10, then 10 − 3 = 7, so k = 7. Check that (2, 7) satisfies the line: 5(2) − 3 = 7, confirming the answer." },
  { id: "t13m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "13", "8"], correct: 0, explanation: "Goal: find the missing value given the mean. The mean equation is (6 + 10 + x)/3 = 9. Multiply both sides by 3: 16 + x = 27. Subtract 16: x = 11. Check: (6 + 10 + 11)/3 = 27/3 = 9, which matches." },
  { id: "t13m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 7 = 22, what is the value of x?", type: "mcq", choices: ["5", "15", "29", "9"], correct: 0, explanation: "Goal: solve for x. Subtract 7 from both sides: 3x = 15. Divide by 3: x = 5. Check by substituting: 3(5) + 7 = 15 + 7 = 22, which matches, so x = 5." },
  { id: "t13m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the sum of the roots. Factor the quadratic: x² − 9x + 20 = (x − 4)(x − 5) = 0, giving roots 4 and 5. Their sum is 4 + 5 = 9. As a check, the sum of roots equals −b/a = −(−9)/1 = 9." },
  { id: "t13m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A price increased from $40 to $46. What was the percent increase?", type: "mcq", choices: ["15%", "6%", "14%", "20%"], correct: 0, explanation: "Goal: find the percent increase. The increase is 46 − 40 = 6 dollars. Divide by the original amount: 6/40 = 0.15. Convert to a percent: 0.15 = 15%. The trap is dividing by the new price (6/46 ≈ 13%); percent change always uses the original value." },
  { id: "t13m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 45° and 65°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["70"], explanation: "Goal: find the third angle. The angles of a triangle sum to 180°. Subtract the two known angles: 180 − 45 − 65 = 180 − 110 = 70°. Check: 45 + 65 + 70 = 180, confirming the third angle is 70°." },
  { id: "t13m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A plumber charges a $40 service fee plus $30 per hour. Which equation gives the total cost C for h hours?", type: "mcq", choices: ["C = 30h + 40", "C = 40h + 30", "C = 70h", "C = 30h − 40"], correct: 0, explanation: "Goal: model the cost. The fixed $40 fee is a constant, and the $30 per hour depends on h, giving the hourly term 30h. The total is C = 30h + 40. The trap is choice B, which swaps the rate and the fixed fee; the per-hour amount must multiply h." },
  { id: "t13m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 2) = x² + bx − 10, what is the value of b?", type: "mcq", choices: ["3", "−3", "7", "10"], correct: 0, explanation: "Goal: find b by expanding. Multiply: (x + 5)(x − 2) = x² − 2x + 5x − 10 = x² + 3x − 10. Matching the middle term to bx gives b = 3. As a check, the constant −10 also matches the given form." },
  { id: "t13m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 300 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["120", "40", "150", "12"], correct: 0, explanation: "Goal: find 40% of 300. Convert the percent to a decimal: 40% = 0.40. Multiply: 0.40 × 300 = 120. The trap is reading 40 as the raw count; the percent must be applied to the total of 300." },
  { id: "t13m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 1) = 3x + 7, what is the value of x?", type: "mcq", choices: ["6", "4", "3", "8"], correct: 0, explanation: "Goal: solve for x. Distribute on the left: 5x − 5 = 3x + 7. Subtract 3x from both sides: 2x − 5 = 7. Add 5: 2x = 12, so x = 6. Check: 5(6 − 1) = 25 and 3(6) + 7 = 25, which match." },
  { id: "t13m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 12 and width 5. What is its perimeter?", type: "mcq", choices: ["34", "60", "17", "24"], correct: 0, explanation: "Goal: find the perimeter. Use P = 2(length + width) = 2(12 + 5) = 2(17) = 34. The trap is computing the area (12 × 5 = 60); perimeter adds the sides rather than multiplying them." },
  { id: "t13m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve the exponential equation. Write 27 as a power of 3: 27 = 3³. Since the bases are equal, the exponents are equal: x − 1 = 3. Add 1: x = 4. Check: 3^(4−1) = 3³ = 27, which matches." },
  { id: "t13m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "90", "35"], correct: 0, explanation: "Goal: convert map inches to real miles. Each inch equals 30 miles, so multiply: 5 × 30 = 150 miles. The trap is adding the scale to the distance (5 + 30 = 35); the relationship is multiplicative, not additive." },
  { id: "t13m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope. Use slope = (y₂ − y₁)/(x₂ − x₁) = (15 − 3)/(6 − 2) = 12/4 = 3. A trap is reversing the order in numerator and denominator inconsistently; keeping both differences in the same order gives the correct value of 3." },
  { id: "t13m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 4x − 5, what value of x makes f(x) = 23?", type: "mcq", choices: ["7", "6", "9", "5"], correct: 0, explanation: "Goal: solve f(x) = 23 for x. Set up 4x − 5 = 23. Add 5 to both sides: 4x = 28. Divide by 4: x = 7. Check: 4(7) − 5 = 28 − 5 = 23, which matches." },
  { id: "t13m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 7. What is its area, in terms of π?", type: "mcq", choices: ["49π", "14π", "7π", "28π"], correct: 0, explanation: "Goal: find the area in terms of π. Use A = πr² = π(7²) = 49π. The trap is using the circumference formula 2πr = 14π; area squares the radius rather than doubling it." },
  { id: "t13m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4x − y = 17 and y = 3, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "20"], correct: 0, explanation: "Goal: solve for x after substituting y. Replace y with 3: 4x − 3 = 17. Add 3 to both sides: 4x = 20. Divide by 4: x = 5. Check: 4(5) − 3 = 20 − 3 = 17, which matches." },
  { id: "t13m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 30-hour week?", type: "mcq", choices: ["660", "52", "630", "720"], correct: 0, explanation: "Goal: find total weekly pay. Multiply the hourly rate by the hours: 22 × 30 = 660 dollars. Break it down if needed: 22 × 3 = 66, then ×10 = 660. So the worker earns $660." },
];

// ─────────────────────── PRACTICE TEST 13 · MATH M2 easy (22) ────────────────
const T13_M_M2E: SatQuestion[] = [
  { id: "t13m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 21, what is the value of x?", type: "grid", gridAnswers: ["12"], explanation: "Goal: solve x + 9 = 21 for x. Since 9 is added to x, undo it by subtracting 9 from both sides: x = 21 − 9 = 12. Check by substituting back: 12 + 9 = 21, which matches. The trap is adding instead of subtracting (getting 30); to isolate x you must do the opposite of the operation attached to it. The answer is x = 12." },
  { id: "t13m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 20% of 80?", type: "mcq", choices: ["16", "20", "8", "160"], correct: 0, explanation: "Goal: find 20% of 80. Convert the percent to a decimal: 20% = 20/100 = 0.20. Multiply by the whole: 0.20 × 80 = 16. Check a different way: 10% of 80 is 8, and 20% is twice that, 8 × 2 = 16, which matches. The trap is choice (C) 8, which is only 10% of 80, or choice (D) 160, which comes from multiplying by 2 instead of 0.20. The correct answer is 16." },
  { id: "t13m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 9 and a width of 4. What is its area?", type: "mcq", choices: ["36", "26", "13", "18"], correct: 0, explanation: "Goal: find the area of the rectangle. Area equals length times width: A = 9 × 4 = 36 square units. Check: a 9-by-4 grid holds 9 × 4 = 36 unit squares, confirming the area. The trap is choice (B) 26, which is the perimeter 2(9 + 4) = 26, or choice (C) 13, which is just the sum 9 + 4; area multiplies the two dimensions rather than adding them. The correct answer is 36." },
  { id: "t13m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 8x = 56, what is the value of x?", type: "mcq", choices: ["7", "8", "48", "64"], correct: 0, explanation: "Goal: solve 8x = 56 for x. The 8 is multiplied by x, so undo it by dividing both sides by 8: x = 56 ÷ 8 = 7. Check by substituting back: 8 × 7 = 56, which matches. The trap is choice (C) 48, which comes from subtracting (56 − 8) instead of dividing; because x is multiplied by 8, division is the correct inverse operation. The answer is x = 7." },
  { id: "t13m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 5² − 4?", type: "grid", gridAnswers: ["21"], explanation: "Goal: evaluate 5² − 4. By order of operations, do the exponent before the subtraction: 5² = 5 × 5 = 25. Then subtract: 25 − 4 = 21. Check by re-reading the steps: square first (25), then take away 4 to get 21. The trap is subtracting before squaring or treating 5² as 5 × 2 = 10; the exponent means 5 multiplied by itself, and it must be computed first. The answer is 21." },
  { id: "t13m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 9 of its 12 games. What fraction of its games did it win?", type: "mcq", choices: ["3/4", "9/12", "2/3", "1/9"], correct: 0, explanation: "Goal: write the win fraction in simplest form. The team won 9 of 12 games, giving the fraction 9/12. Reduce by dividing numerator and denominator by their greatest common factor, 3: 9 ÷ 3 = 3 and 12 ÷ 3 = 4, so 9/12 = 3/4. Check: 3/4 = 0.75 and 9/12 = 0.75, so they are equal. The trap is choice (B) 9/12, which is correct in value but not in simplest form, the form the question asks for. The answer is 3/4." },
  { id: "t13m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 5 = 14, what is the value of x?", type: "grid", gridAnswers: ["19"], explanation: "Goal: solve x − 5 = 14 for x. Since 5 is subtracted from x, undo it by adding 5 to both sides: x = 14 + 5 = 19. Check by substituting back: 19 − 5 = 14, which matches. The trap is subtracting 5 instead of adding it (getting 9); the inverse of subtraction is addition. The answer is x = 19." },
  { id: "t13m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 12, 18, and 30?", type: "mcq", choices: ["20", "30", "18", "60"], correct: 0, explanation: "Goal: find the average (mean) of the three numbers. Add them: 12 + 18 + 30 = 60. Divide by the count of values, 3: 60 ÷ 3 = 20. Check that 20 is reasonable: it sits between the smallest (12) and largest (30) value, as a mean must. The trap is choice (D) 60, which is the sum before dividing by 3; the mean requires dividing the total by how many numbers there are. The answer is 20." },
  { id: "t13m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 6. What is its perimeter?", type: "mcq", choices: ["24", "36", "12", "30"], correct: 0, explanation: "Goal: find the perimeter of the square. A square has four equal sides, so the perimeter is 4 times the side length: P = 4 × 6 = 24. Check by adding the four sides: 6 + 6 + 6 + 6 = 24, which matches. The trap is choice (B) 36, which is the area (6 × 6 = 36); perimeter adds the side lengths, while area multiplies side by side. The answer is 24." },
  { id: "t13m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 3 = 15, what is the value of x?", type: "mcq", choices: ["6", "9", "12", "5"], correct: 0, explanation: "Goal: solve 2x + 3 = 15 for x. First undo the addition by subtracting 3 from both sides: 2x = 12. Then undo the multiplication by dividing both sides by 2: x = 6. Check by substituting: 2(6) + 3 = 12 + 3 = 15, which matches. The trap is choice (C) 12, which is the value of 2x before dividing by 2; remember to finish by dividing out the coefficient. The answer is x = 6." },
  { id: "t13m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 8, what is f(6)?", type: "mcq", choices: ["14", "48", "2", "68"], correct: 0, explanation: "Goal: evaluate the function f(x) = x + 8 at x = 6. Substitute 6 for x: f(6) = 6 + 8 = 14. Check: the function simply adds 8 to its input, and 6 + 8 = 14. The trap is choice (B) 48, which comes from multiplying 6 × 8; the rule here is addition, not multiplication. The answer is f(6) = 14." },
  { id: "t13m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 5 notebooks for $10. How much do 8 notebooks cost?", type: "mcq", choices: ["$16", "$10", "$18", "$13"], correct: 0, explanation: "Goal: find the cost of 8 notebooks at the same rate. First find the unit price: $10 ÷ 5 = $2 per notebook. Then multiply by 8: 8 × $2 = $16. Check with a proportion: 5 notebooks/$10 = 8 notebooks/$x gives 5x = 80, so x = 16, matching. The trap is choice (D) $13, which comes from adding $3 for the 3 extra notebooks at $1 each instead of the true $2 each; each notebook costs $2. The answer is $16." },
  { id: "t13m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 48, what is the value of x?", type: "mcq", choices: ["8", "6", "42", "54"], correct: 0, explanation: "Goal: solve 6x = 48 for x. The 6 multiplies x, so undo it by dividing both sides by 6: x = 48 ÷ 6 = 8. Check by substituting: 6 × 8 = 48, which matches. The trap is choice (C) 42, which comes from subtracting (48 − 6) instead of dividing; division is the correct inverse of multiplication. The answer is x = 8." },
  { id: "t13m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 8 and a height of 5. What is its area?", type: "grid", gridAnswers: ["20"], explanation: "Goal: find the triangle's area. Use the formula Area = (1/2)(base)(height). Substitute base = 8 and height = 5: Area = (1/2)(8)(5) = (1/2)(40) = 20. Check: a triangle is half of the 8-by-5 rectangle, whose area is 40, so half is 20. The trap is forgetting the 1/2 factor and reporting 40 (the full rectangle); a triangle is half that. The answer is 20." },
  { id: "t13m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 25% of 60?", type: "mcq", choices: ["15", "25", "35", "12"], correct: 0, explanation: "Goal: find 25% of 60. Since 25% equals 1/4, take one quarter of 60: 60 ÷ 4 = 15. Check the other way: 0.25 × 60 = 15, which matches. The trap is choice (B) 25, which just echoes the percent number rather than applying it to 60; a percent must be multiplied by the whole. The answer is 15." },
  { id: "t13m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 7, what is the value of x?", type: "mcq", choices: ["21", "10", "4", "3.5"], correct: 0, explanation: "Goal: solve x/3 = 7 for x. The x is divided by 3, so undo it by multiplying both sides by 3: x = 7 × 3 = 21. Check by substituting: 21 ÷ 3 = 7, which matches. The trap is choice (C) 4, which comes from subtracting (7 − 3) instead of multiplying; the inverse of dividing by 3 is multiplying by 3. The answer is x = 21." },
  { id: "t13m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 3³?", type: "mcq", choices: ["27", "9", "12", "6"], correct: 0, explanation: "Goal: evaluate 3³. The exponent 3 means 3 multiplied by itself three times: 3 × 3 × 3. Compute step by step: 3 × 3 = 9, then 9 × 3 = 27. The trap is choice (C) 12, which comes from multiplying 3 × 4 or adding wrongly, or choice (D) 6, from doing 3 × 2; an exponent means repeated multiplication of the base, not the base times the exponent. The answer is 27." },
  { id: "t13m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 150 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["50", "150", "450", "30"], correct: 0, explanation: "Goal: find the average speed in miles per hour. Speed equals distance divided by time: 150 miles ÷ 3 hours = 50 miles per hour. Check by reversing: 50 mph × 3 hours = 150 miles, which matches the distance given. The trap is choice (C) 450, which comes from multiplying 150 × 3 instead of dividing; speed is distance per unit time, so you divide. The answer is 50 mph." },
  { id: "t13m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x − 8 = 12, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve 4x − 8 = 12 for x. First undo the subtraction by adding 8 to both sides: 4x = 20. Then undo the multiplication by dividing both sides by 4: x = 5. Check by substituting: 4(5) − 8 = 20 − 8 = 12, which matches. The trap is dividing before adding the 8 back; isolate the 4x term first, then divide. The answer is x = 5." },
  { id: "t13m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a radius of 8. What is its diameter?", type: "mcq", choices: ["16", "8", "4", "64"], correct: 0, explanation: "Goal: find the diameter from the radius. The diameter is twice the radius: d = 2r = 2 × 8 = 16. Check: the radius should be half the diameter, and half of 16 is 8, the given radius, so it matches. The trap is choice (C) 4, which halves the radius instead of doubling it; the diameter is always larger than the radius. The answer is 16." },
  { id: "t13m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x and x = 5, what is the value of y?", type: "mcq", choices: ["15", "8", "2", "5"], correct: 0, explanation: "Goal: find y given y = 3x and x = 5. Substitute 5 for x: y = 3 × 5 = 15. Check: with y = 15 and x = 5, the ratio y/x = 15/5 = 3, matching the coefficient. The trap is choice (B) 8, which comes from adding 3 + 5 instead of multiplying; y = 3x means 3 times x, so you multiply. The answer is y = 15." },
  { id: "t13m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A box holds 6 green and 9 yellow balls. What fraction of the balls are green?", type: "mcq", choices: ["2/5", "6/9", "1/2", "3/5"], correct: 0, explanation: "Goal: write the fraction of green balls in simplest form. There are 6 green out of a total of 6 + 9 = 15 balls, giving 6/15. Reduce by dividing top and bottom by their common factor 3: 6 ÷ 3 = 2 and 15 ÷ 3 = 5, so 6/15 = 2/5. Check: 2/5 = 0.4 and 6/15 = 0.4, equal. The trap is choice (B) 6/9, which wrongly uses the count of yellow balls (9) as the denominator instead of the total (15); the fraction of green must be over all the balls. The answer is 2/5." },
];

