const T13_M_M2H: SatQuestion[] = [
  { id: "t13m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for the positive root. Add 64 to both sides: x² = 64. Take the square root: x = ±8. Because the problem requires x > 0, keep x = 8. The trap is reporting −8; the positivity condition rules it out." },
  { id: "t13m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 3y = 27 and x − 3y = −2, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "3"], correct: 0, explanation: "Goal: solve the system for x. Add the two equations to eliminate y: (4x + x) + (3y − 3y) = 27 + (−2), giving 5x = 25, so x = 5. Check by finding y: 5 − 3y = −2 gives y = 7/3, and 4(5) + 3(7/3) = 20 + 7 = 27, confirming x = 5." },
  { id: "t13m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^x = 64, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve 2^x = 64 for x. Rewrite 64 as a power of 2 by repeated doubling: 2, 4, 8, 16, 32, 64, which is 2⁶. So 2^x = 2⁶, and since the bases are equal, the exponents must be equal: x = 6. Check: 2⁶ = 64, which matches. The trap is dividing 64 by 2 to get 32 and treating that as the answer; you need the exponent that produces 64, not the result of one division. The answer is x = 6." },
  { id: "t13m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $120 is marked up by 30%. What is the new price?", type: "mcq", choices: ["$156", "$150", "$144", "$90"], correct: 0, explanation: "Goal: find the marked-up price. Compute the markup: 30% of 120 = 0.30 × 120 = 36. Add it to the original: 120 + 36 = $156. The trap is subtracting the markup (giving $84); a markup raises the price." },
  { id: "t13m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 8 and 15. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["17"], explanation: "Goal: find the hypotenuse of the right triangle. By the Pythagorean theorem, c² = a² + b² = 8² + 15² = 64 + 225 = 289. Take the positive square root: c = √289 = 17. Check: 8² + 15² = 64 + 225 = 289 = 17², confirming it; this is the well-known 8-15-17 right triangle. The trap is adding the legs directly (8 + 15 = 23) instead of using the squares; the Pythagorean theorem squares each leg before summing. The answer is 17." },
  { id: "t13m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(3))?", type: "mcq", choices: ["19", "7", "21", "25"], correct: 0, explanation: "Goal: compute the composed value. First find the inner value: p(3) = 3(3) − 2 = 7. Then apply p again: p(7) = 3(7) − 2 = 21 − 2 = 19. The trap is stopping at 7; the outer p must still be applied." },
  { id: "t13m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 2y = 19 and x = y + 2, what is the value of y?", type: "grid", gridAnswers: ["2.6", "13/5"], explanation: "Goal: solve the system for y. Substitute x = y + 2 into the first equation: 3(y + 2) + 2y = 19, which gives 3y + 6 + 2y = 19, so 5y + 6 = 19. Subtract 6: 5y = 13, so y = 13/5 = 2.6. Check: x = 13/5 + 2 = 23/5, and 3(23/5) + 2(13/5) = 69/5 + 26/5 = 95/5 = 19, confirming y = 2.6." },
  { id: "t13m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 12 has its vertex at (h, k). What is the value of h?", type: "mcq", choices: ["4", "−4", "8", "2"], correct: 0, explanation: "Goal: find the x-coordinate h of the parabola's vertex for y = x² − 8x + 12. Use the vertex formula h = −b/(2a) with a = 1 and b = −8: h = −(−8)/(2·1) = 8/2 = 4. Check by symmetry: the roots of x² − 8x + 12 = (x − 2)(x − 6) are 2 and 6, and the vertex sits halfway between them at (2 + 6)/2 = 4, confirming h = 4. The trap is choice (B) −4, from forgetting that b = −8 makes −b positive. The answer is h = 4." },
  { id: "t13m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, an acute angle θ has cos θ = 5/13. What is sin θ?", type: "mcq", choices: ["12/13", "5/12", "13/12", "13/5"], correct: 0, explanation: "Goal: find sin θ from cos θ. With adjacent 5 and hypotenuse 13, find the opposite leg using the 5-12-13 triple: opposite = √(13² − 5²) = √(169 − 25) = √144 = 12. Then sin θ = opposite/hypotenuse = 12/13. The trap is sticking with the 5; sine uses the opposite side." },
  { id: "t13m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "mcq", choices: ["10", "5", "25", "50"], correct: 0, explanation: "Goal: find b. A perfect square (x + a)² = x² + 2ax + a² must have a² = 25, so a = 5 (taking the positive value since b > 0). Then b = 2a = 2(5) = 10. Check: (x + 5)² = x² + 10x + 25, so b = 10." },
  { id: "t13m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−1", "5", "−6"], correct: 0, explanation: "Goal: find the y-intercept b. Use y = −3x + b and plug in the point (2, 5): 5 = −3(2) + b, so 5 = −6 + b. Add 6 to both sides: b = 11. Check: at x = 0, y = 11, and the line through (2,5) with slope −3 gives 5 = −6 + 11, confirming b = 11." },
  { id: "t13m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a tablet costs $300. What was the original price?", type: "mcq", choices: ["$400", "$375", "$360", "$325"], correct: 0, explanation: "Goal: recover the original price. A 25% discount leaves 75% of the original, so 0.75 × original = 300. Divide: original = 300 ÷ 0.75 = 400. The trap is adding 25% to 300 (giving $375); the discount applies to the larger original, not the reduced price." },
  { id: "t13m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 81 with a < 0, what is the value of a?", type: "mcq", choices: ["−9", "9", "−81", "−40.5"], correct: 0, explanation: "Goal: find the negative input a where f(a) = a² = 81. Take the square root of both sides: a = ±√81 = ±9. The condition a < 0 selects the negative root, so a = −9. Check: (−9)² = 81, which matches. The trap is choice (B) 9, the positive root, which violates the requirement a < 0; both ±9 square to 81, so the sign condition is what decides. The answer is a = −9." },
  { id: "t13m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: find the cylinder's volume. Use V = πr²h = π(4²)(6) = π(16)(6) = 96π. The trap is forgetting to square the radius (using 4 × 6 = 24); the formula squares r before multiplying by the height." },
  { id: "t13m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["1.333", "4/3"], explanation: "Goal: solve for x. Subtract 1/4 from both sides: 1/x = 1 − 1/4 = 3/4. Take the reciprocal of both sides: x = 4/3 ≈ 1.333. Check: 1/(4/3) + 1/4 = 3/4 + 1/4 = 1, which matches." },
  { id: "t13m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "3"], correct: 0, explanation: "Goal: find the product of the roots of x² − 7x + 10 = 0. Factor: x² − 7x + 10 = (x − 2)(x − 5) = 0, giving roots x = 2 and x = 5. Their product is 2 × 5 = 10. Check using Vieta's formula: the product of roots equals c/a = 10/1 = 10, which matches. The trap is choice (B) 7, which is the SUM of the roots (2 + 5), not the product; the question asks for the product. The answer is 10." },
  { id: "t13m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of red to blue tiles in a box is 2:7. If there are 45 tiles total, how many are blue?", type: "mcq", choices: ["35", "10", "30", "14"], correct: 0, explanation: "Goal: find the number of blue tiles. The ratio parts total 2 + 7 = 9, so each part equals 45 ÷ 9 = 5 tiles. Blue corresponds to 7 parts: 7 × 5 = 35. The trap is using the red share (2 parts = 10); the question asks for blue." },
  { id: "t13m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 5, what is the area of the larger?", type: "grid", gridAnswers: ["80"], explanation: "Goal: find the larger area. Areas of similar figures scale by the square of the linear ratio, so the factor is 4² = 16. Multiply: 5 × 16 = 80. The trap is multiplying by 4 (giving 20); area scales by the square of the scale factor, not the factor itself." },
  { id: "t13m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x − 5) = 6, what is the value of x?", type: "mcq", choices: ["41", "11", "31", "1"], correct: 0, explanation: "Goal: solve √(x − 5) = 6 for x. Square both sides to remove the radical: x − 5 = 6² = 36. Add 5 to both sides: x = 41. Check: √(41 − 5) = √36 = 6, which matches. The trap is choice (B) 11, which comes from adding 5 to 6 (the un-squared right side) instead of squaring first; you must square both sides before solving. The answer is x = 41." },
  { id: "t13m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 2y = 24 and y = 3, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "8"], correct: 0, explanation: "Goal: solve 5x − 2y = 24 for x after substituting y = 3. Replace y: 5x − 2(3) = 24, so 5x − 6 = 24. Add 6 to both sides: 5x = 30. Divide by 5: x = 6. Check: 5(6) − 2(3) = 30 − 6 = 24, which matches. The trap is forgetting to multiply 2 × 3 and instead subtracting only 3; the term is 2y = 6, so 6 must be added back. The answer is x = 6." },
  { id: "t13m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "mcq", choices: ["3", "−3", "9", "6"], correct: 0, explanation: "Goal: find x where g(x) = x² − 6x + 9 = 0. Recognize the perfect-square trinomial: x² − 6x + 9 = (x − 3)². Set it to zero: (x − 3)² = 0, so x − 3 = 0, giving x = 3 (a double root). Check: 3² − 6(3) + 9 = 9 − 18 + 9 = 0, which matches. The trap is choice (B) −3, from misremembering the factor as (x + 3); the middle term −6x requires (x − 3). The answer is x = 3." },
  { id: "t13m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of insects triples every day. If it starts at 20, how many are there after 3 days?", type: "mcq", choices: ["540", "180", "60", "1620"], correct: 0, explanation: "Goal: find the population after 3 days of tripling. Multiply by 3 three times: 20 × 3³ = 20 × 27 = 540. As a check, day 1 gives 60, day 2 gives 180, and day 3 gives 540. The trap is multiplying by 3 only once (60) instead of for all three days." },
];

